"use client";
import {useRef} from "react";
import { VelocityClip } from "@/components/application/animations/expanded/scroll/velocity-clip";

// Install the component assets or replace these image URLs with your own.
const imageStyle = { width: "100%", height: "100%", objectFit: "cover", display: "block" } as const;

export default function Example(){
 const scrollContainer=useRef<HTMLDivElement>(null);
 return <div ref={scrollContainer} tabIndex={0} role="region" aria-label="Scroll demonstration" style={{height:600,overflowY:"auto",overscrollBehavior:"contain",background:"#efefed",color:"#151515"}}>
  <div style={{height:"320%",position:"relative"}}>
   <div style={{position:"sticky",top:0,height:600,overflow:"hidden"}}>
        <VelocityClip
          scrollContainer={scrollContainer}
          intensity={1}
          maxInset={24}
          maxVelocity={2400}
          scaleIntensity={0.1}
          axis={"x"}
          borderRadius={10}
        ><img src="/assets/zeus/hero_run_02.jpg" alt="Runner in motion" style={imageStyle} /></VelocityClip>
   </div>
  </div>
 </div>;
}

